def build():
    sources=[dict(id=idx,name=name,publisher=publisher,url=url,retrieved=DATE,license=license_,usedFor=used,notes=notes,
                  status='stand-in' if idx in ('assumptions','nadac') else 'cached') for idx,name,publisher,url,license_,used,notes in SOURCES]
    save(PUBLIC/'sources.json',sources)
    facts=[
        ('helene-baxter-60pct','Hurricane Helene flooded Baxter’s North Cove plant on September 27, 2024. AHA reported that the plant supplied approximately 60% of US IV solutions.',['baxter-helene','aha-north-cove']),
        ('rocky-mount','A July 19, 2023 tornado disrupted Pfizer’s Rocky Mount site. Pfizer reported the worst damage in its warehouse and imposed emergency ordering on selected injectables.',['pfizer-tornado','pfizer-products']),
        ('maria','Hurricane Maria disrupted Puerto Rico production in September 2017 and worsened existing small-volume IV-solution shortages.',['fda-maria','baxter-maria']),
        ('shortage-record','ASHP and the University of Utah tracked a record 323 active US drug shortages in the first quarter of 2024.',['ashp-record']),
        ('labor-cost','Vizient’s 2019 survey estimated that US hospitals spent $359 million a year in labor to manage drug shortages.',['vizient']),
    ]
    save(PUBLIC/'facts.json',[dict(id=idx,text=text,sourceIds=ids,verified=True) for idx,text,ids in facts])
    save(PUBLIC/'trends.json',dict(disasters=[dict(year=2022,count=18),dict(year=2023,count=28),dict(year=2024,count=27)],
         shortages=[dict(year=2022,period='Q4 2022',active=260),dict(year=2023,period='Q3 2023',active=309),dict(year=2024,period='Q1 2024',active=323)],
         sourceIds=['noaa-trends','ashp-trends','ashp-record']))
